import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(const float* x, const float* weight, float* output,
                                int batch_size, int input_size, int hidden_size,
                                float scaling_factor) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < batch_size) {
        float sum = 0.0f;

        // Fused: MatMul + Div + Sum + Scale
        for(int j = 0; j < hidden_size; ++j) {
            for(int k = 0; k < input_size; ++k) {
                sum += x[i * input_size + k] * weight[j * input_size + k];
            }
        }

        output[i] = sum * (scaling_factor / 2.0f);
    }
}

torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor weight, float scaling_factor) {
    auto batch_size = x.size(0);
    auto output = torch::zeros({batch_size, 1}, x.options());

    int block_size = 256;
    int num_blocks = (batch_size + block_size - 1) / block_size;

    fused_op_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        x.size(1),
        weight.size(0),
        scaling_factor
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor weight, float scaling_factor);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(hidden_size, input_size))
        self.scaling_factor = scaling_factor
        self.fused_op = fused_op

    def forward(self, x):
        return self.fused_op.fused_op_cuda(x, self.weight, self.scaling_factor)
